    case rFault of Inl f \<Rightarrow> withoutPreemption $ ?hFault f
    | Inr a \<Rightarrow>
        doE rError <- withoutPreemption $ runExceptT $ ?mError a;
            case rError of Inl e \<Rightarrow> withoutPreemption $ ?hError e
            | Inr b \<Rightarrow> ?mFinalise b
        odE
odE"}
