   totalBits <- return (objSizeBits + ?groupSizeBits);
   unless (fromPPtr ?ptr && mask totalBits = 0) $ alignError totalBits;
   ps <- gets ksPSpace;
   end <- return (fromPPtr ?ptr + (1 `~shiftL~` totalBits - 1));
   (before, uu_) <- return (lookupAround2 end (psMap ps));
   case before of None \<Rightarrow> return ()
   | Some (x, xa) \<Rightarrow> haskell_assert (x < fromPPtr ?ptr) [];
   addresses <-
   return
    (map (\<lambda>n. fromPPtr ?ptr + n `~shiftL~` objSizeBits)
      [0 .e. 1 `~shiftL~` ?groupSizeBits - 1]);
   map' <-
   return
    (foldR (\<lambda>addr. data_map_insert addr ?val) (psMap ps) addresses);
   ps' <- return (psMap_update (\<lambda>_. map') ps);
   modify (ksPSpace_update (\<lambda>_. ps'))
od"}
