    do pde <- ARM_A.get_pde pdePtr;
       return $
       case pde of
       ARM_A.SectionPDE x xa xb xc \<Rightarrow>
         x = addrFromPPtr ?pptr \<and> ?pgsz = ARM.ARMSection
       | ARM_A.SuperSectionPDE x xa xb \<Rightarrow>
           x = addrFromPPtr ?pptr \<and> ?pgsz = ARM.ARMSuperSection
       | _ \<Rightarrow> False
    od"}
